Here's how to handle draft persistence with .NET MAUI's lifecycle events:

```csharp
// NotesPage.xaml.cs
public partial class NotesPage : ContentPage
{
    private const string DraftKey = "notes_draft";

    public NotesPage()
    {
        InitializeComponent();
    }

    protected override void OnAppearing()
    {
        base.OnAppearing();
        // Restore draft
        if (Preferences.ContainsKey(DraftKey))
            EditorField.Text = Preferences.Get(DraftKey, string.Empty);
    }

    private void SaveDraft()
    {
        Preferences.Set(DraftKey, EditorField.Text ?? string.Empty);
    }

    public void ClearDraft()
    {
        Preferences.Remove(DraftKey);
    }
}
```

Then wire up the app lifecycle in `App.xaml.cs`:

```csharp
// App.xaml.cs
public partial class App : Application
{
    public App()
    {
        InitializeComponent();
        MainPage = new NavigationPage(new NotesPage());
    }

    protected override Window CreateWindow(IActivationState? activationState)
    {
        var window = base.CreateWindow(activationState);

        window.Backgrounding += (s, e) =>
        {
            // Save draft when app goes to background
            if (GetCurrentPage() is NotesPage notesPage)
                notesPage.SaveDraft();
        };

        window.Resuming += (s, e) =>
        {
            // OnAppearing handles restore automatically
        };

        return window;
    }

    private Page? GetCurrentPage()
    {
        if (MainPage is NavigationPage nav)
            return nav.CurrentPage;
        return MainPage;
    }
}
```

**Key points:**

- **`Preferences`** — simple key-value store that persists across app restarts (backed by `SharedPreferences` on Android, `NSUserDefaults` on iOS).
- **`window.Backgrounding`** — fires when the app loses focus; save here to avoid data loss.
- **`OnAppearing`** — restores the draft when the page is displayed.
- Call `ClearDraft()` after the user explicitly saves/submits the note.

For larger drafts, swap `Preferences` for `SecureStorage` or write to `FileSystem.AppDataDirectory` instead.
